mapper.select:
SELECT

FROM EVENT_ACTION_LOG L
WHERE L.SEQ = #{seq}

SELECT

FROM EVENT_ACTION_LOG L
WHERE L.PARTICIPANT_SEQ = #{participantSeq}
AND L.ACTION_TYPE_SEQ = #{actionTypeSeq}
ORDER BY L.ACTION_TIME DESC

SELECT EXISTS(
    SELECT 1 FROM EVENT_ACTION_LOG
    WHERE PARTICIPANT_SEQ = #{participantSeq}
    AND ACTION_TYPE_SEQ = #{actionTypeSeq}
)

SELECT

FROM EVENT_ACTION_LOG L
INNER JOIN EVENT_PARTICIPANT P ON L.PARTICIPANT_SEQ = P.SEQ
INNER JOIN SURVEY_USER U ON P.SURVEY_USER_SEQ = U.SEQ
INNER JOIN EVENT_ACTION_TYPE T ON L.ACTION_TYPE_SEQ = T.SEQ
WHERE P.EVENT_SEQ = #{eventSeq}

    AND T.ACTION_CODE = #{actionCode}

ORDER BY L.ACTION_TIME DESC
LIMIT #{limit} OFFSET #{offset}

SELECT

FROM EVENT_ACTION_LOG L
INNER JOIN EVENT_PARTICIPANT P ON L.PARTICIPANT_SEQ = P.SEQ
INNER JOIN SURVEY_USER U ON P.SURVEY_USER_SEQ = U.SEQ
INNER JOIN EVENT_ACTION_TYPE T ON L.ACTION_TYPE_SEQ = T.SEQ
WHERE P.EVENT_SEQ = #{eventSeq}
AND T.ACTION_CODE = #{actionCode}
ORDER BY L.ACTION_TIME DESC

    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT L.PARTICIPANT_SEQ)
FROM EVENT_ACTION_LOG L
INNER JOIN EVENT_PARTICIPANT P ON L.PARTICIPANT_SEQ = P.SEQ
WHERE P.EVENT_SEQ = #{eventSeq}
AND L.ACTION_TYPE_SEQ = #{actionTypeSeq}

mapper.insert:
INSERT INTO EVENT_ACTION_LOG (
    PARTICIPANT_SEQ, ACTION_TYPE_SEQ, ACTION_TIME,
    DEVICE_INFO, CONFIRMED_BY, MEMO
) VALUES (
    #{participantSeq}, #{actionTypeSeq}, NOW(),
    #{deviceInfo}, #{confirmedBy}, #{memo}
)

mapper.delete:
DELETE L FROM EVENT_ACTION_LOG L
INNER JOIN EVENT_PARTICIPANT P ON L.PARTICIPANT_SEQ = P.SEQ
WHERE P.EVENT_SEQ = #{eventSeq}
